using System;
using System.Collections.Generic;
using System.Collections.ObjectModel;
using System.Linq;
using System.Reflection;
using System.Diagnostics;
using Barotrauma;
using Microsoft.Xna.Framework;

namespace CrabUIUser
{
  public partial class ModuleInjection : Experiment
  {
    public class Component
    {
      //should be autogenerated
      public void WireModules()
      {
        Props.PropB.PropA = Props.PropA;
        Props.TreeProp.TreeModule = TreeModule;
        Props.TreeProp.GetTreeProp = (host) => host.Props.TreeProp;
      }

      public class PropsWrapper
      {
        public PropA PropA { get; } = new();
        public PropB PropB { get; } = new();
        public TreeProp TreeProp { get; } = new();
      }

      public PropsWrapper Props { get; } = new();
      public ComponentTreeModule TreeModule { get; } = new();
      public Injector Injector { get; } = new();

      public Component()
      {

      }
    }
  }



}